config.script:
# One handler for every mutation: create / edit / delete / move / resize,
# including recurring-event scope (series vs single occurrence).
ev = event.event
action = event.action
scope = getattr(event, "scope", None)            # 'series' | 'occurrence' | None
seriesId = getattr(event, "seriesId", None)
occDate = getattr(event, "occurrenceDate", None)
events = [dict(e) for e in self.props.data.events]

def idx_of(eid):
	for i in range(len(events)):
		if events[i].get("id") == eid:
			return i
	return -1

def row_from(e):
	return {"id": e.id, "title": e.title, "start": e.start, "end": e.end,
		"allDay": e.allDay, "category": e.category, "description": e.description,
		"rrule": getattr(e, "rrule", None)}

def upsert(row):
	i = idx_of(row.get("id"))
	if i >= 0:
		events[i] = row
	else:
		events.append(row)

def add_exdate(sid, d):
	i = idx_of(sid)
	if i < 0:
		return
	base = dict(events[i])
	rr = dict(base.get("rrule") or {})
	ex = list(rr.get("exdate") or [])
	if d not in ex:
		ex.append(d)
	rr["exdate"] = ex
	base["rrule"] = rr
	events[i] = base

if scope == "occurrence":
	add_exdate(seriesId, occDate)          # hide this date in the series
	if action == "delete":
		events = [e for e in events if e.get("id") != ev.id]
	else:
		upsert(row_from(ev))               # standalone override for this date
elif scope == "series":
	if action == "delete":
		events = [e for e in events if e.get("id") != seriesId]
	else:
		upsert(row_from(ev))               # the base series (with its rule)
else:
	if action == "delete":
		events = [e for e in events if e.get("id") != ev.id]
	else:
		upsert(row_from(ev))

self.props.data.events = events
